// TestSurface pins the size of the generated surface. A header update that
// adds or removes a declaration should change this number in the same commit
// that changes the bindings, so that neither can move unnoticed.
func TestSurface(t *testing.T) {
	const (
		records = 59
		enums   = 38
		funcs   = 2
	)
	if got := len(Symbols()); got != funcs {
		t.Errorf("Symbols() = %d entries, want %d", got, funcs)
	}
	_ = records
	_ = enums
}
